const listDueAutoSpaceLifecycles = `-- name: ListDueAutoSpaceLifecycles :many
with reclaim_expired_claims as (
    update auto_space_lifecycles
    set state = 'active', claim_expires_at = null, updated_at = now()
    where state = 'archiving'
      and claim_expires_at <= $1
    returning tenant_id, space_id
)
select lifecycle.tenant_id, lifecycle.space_id, lifecycle.deadline_at,
       lifecycle.creator_arrival_handle, lifecycle.state, lifecycle.claim_expires_at,
       lifecycle.next_retry_at,
       lifecycle.retry_count, lifecycle.last_error_family, lifecycle.archive_completed_at,
       lifecycle.journey_id, lifecycle.created_at, lifecycle.updated_at
from auto_space_lifecycles lifecycle
left join reclaim_expired_claims reclaimed
  on reclaimed.tenant_id = lifecycle.tenant_id
 and reclaimed.space_id = lifecycle.space_id
left join space_public_arrivals creator_arrival
  on creator_arrival.tenant_id = lifecycle.tenant_id
 and creator_arrival.space_id = lifecycle.space_id
 and creator_arrival.arrival_handle = lifecycle.creator_arrival_handle
where (lifecycle.state = 'active' or reclaimed.tenant_id is not null)
  and (lifecycle.deadline_at <= $1
       or (
           creator_arrival.state in ('left', 'rejected', 'unavailable')
           and not exists (
               select 1
               from participants active_participant
               where active_participant.tenant_id = lifecycle.tenant_id
                 and active_participant.space_id = lifecycle.space_id
                 and active_participant.episode_id = creator_arrival.episode_id
                 and active_participant.status in ('joining', 'active', 'leaving')
           )
           -- The creator's departure waits the Episode's linger window after the
           -- last departure, so a quick Rejoin continues the same call.
           and greatest(
               creator_arrival.terminal_at,
               (
                   select max(p.left_at)
                   from participants p
                   where p.tenant_id = creator_arrival.tenant_id
                     and p.space_id = creator_arrival.space_id
                     and p.episode_id = creator_arrival.episode_id
                     and p.joined_at is not null
               )
           ) + make_interval(secs => coalesce((
               select (e.config_snapshot->>'linger_window_seconds')::integer
               from episodes e
               where e.tenant_id = creator_arrival.tenant_id
                 and e.space_id = creator_arrival.space_id
                 and e.id = creator_arrival.episode_id
           ), 0)) <= $1
       ))
  and (lifecycle.next_retry_at is null or lifecycle.next_retry_at <= $1)
order by lifecycle.deadline_at, lifecycle.tenant_id, lifecycle.space_id
limit $2::integer
`

type ListDueAutoSpaceLifecyclesParams struct {
	NowAt    pgtype.Timestamptz `json:"now_at"`
	PageSize int32              `json:"page_size"`
}

func (q *Queries) ListDueAutoSpaceLifecycles(ctx context.Context, arg ListDueAutoSpaceLifecyclesParams) ([]AutoSpaceLifecycle, error) {
	rows, err := q.db.Query(ctx, listDueAutoSpaceLifecycles, arg.NowAt, arg.PageSize)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []AutoSpaceLifecycle
	for rows.Next() {
		var i AutoSpaceLifecycle
		if err := rows.Scan(
			&i.TenantID,
			&i.SpaceID,
			&i.DeadlineAt,
			&i.CreatorArrivalHandle,
			&i.State,
			&i.ClaimExpiresAt,
			&i.NextRetryAt,
			&i.RetryCount,
			&i.LastErrorFamily,
			&i.ArchiveCompletedAt,
			&i.JourneyID,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listPendingSpacePublicAdmissionRequests = `-- name: ListPendingSpacePublicAdmissionRequests :many

select public.request_handle, public.arrival_handle, public.tenant_id, public.space_id, public.display_name, public.state, public.requested_at, public.expires_at, public.decided_at, public.decided_by, public.decision_request_key,
       (case when live.status = 'admitted' then 'approved'
             when live.status = 'denied' then 'denied'
             when live.status = 'expired' then 'expired'
             when live.admission_request_id is null and public.state = 'pending' and public.expires_at <= now() then 'expired'
             else public.state end)::text as effective_state,
       coalesce(live.status, '')::text as admission_status,
       live.decision_external_operation_id,
       coalesce(operation.operation_name, '')::text as decision_operation
from space_public_admission_requests public
left join sync_admission_requests live
  on live.tenant_id = public.tenant_id and live.space_id = public.space_id
  and live.admission_request_id = public.request_handle
left join sync_external_operations operation
  on operation.tenant_id = live.tenant_id and operation.episode_id = live.episode_id
  and operation.external_operation_id = live.decision_external_operation_id
where public.tenant_id = $1 and public.space_id = $2
  and (not $3::boolean or public.state = 'pending')
  and (not $3::boolean or $4::text <> 'pending' or public.expires_at > now())
  and (not $3::boolean or (case when live.status = 'admitted' then 'approved'
             when live.status = 'denied' then 'denied'
             when live.status = 'expired' then 'expired'
             when live.admission_request_id is null and public.state = 'pending' and public.expires_at <= now() then 'expired'
             else public.state end)::text = $4::text)
order by public.requested_at, public.request_handle
limit $5::integer
`

